/* CRM v4 — warm neutral desk, 8px rhythm, dense type.
   Light page #F7F4F0, panel #F4F7F6, table head #F4F1EC, ink #3B332E, accent #007BFF.
   Chrome pad stays 10px. Touch targets grow to 44px under 768px. */

[data-crmv4-root] {
  --chrome-pad: 10px;
  --c4-1: 8px;
  --c4-2: 15px;
  --c4-3: 25px;
  --c4-4: 40px;
  --c4-control: 30px;
  --c4-touch: 44px;
  --c4-radius: 10px;
  --c4-page: #f4f0e8;
  --c4-canvas: #f7f4ee;
  --c4-card: #fffdf8;
  --c4-table: #f3ece2;
  --c4-ink: #2a2622;
  --c4-muted: #5f564e;
  --c4-line: #e6dccf;
  --c4-line-strong: #d4c6b2;
  --c4-accent: #a6854e;
  --c4-accent-ink: #7a5e30;
  --c4-danger: #de260b;
  --c4-coral: #ff6e5e;
  --c4-mint: #71d6a3;
  --c4-pos: #1f8a4c;
  --c4-neg: #de260b;
  --c4-shadow: 0 12px 40px rgba(59, 51, 46, 0.05);
  --c4-hover: #f7f4ee;
  color: var(--c4-ink);
  background: var(--c4-page);
  font-family: var(--font-inter, "Avenir Next"), var(--font-inter-ext, "Segoe UI"), "Avenir Next", "Segoe UI", sans-serif;
  font-weight: 400;
  letter-spacing: 0.01em;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr) auto;
  height: 100vh;
  height: 100dvh;
  max-height: 100dvh;
  max-width: 100%;
  overflow-x: clip;
}

[data-crmv4-root][data-theme="dark"] {
  --c4-page: #12110f;
  --c4-canvas: #1a1815;
  --c4-card: #221f1b;
  --c4-table: #2c2823;
  --c4-ink: #f6f1e8;
  --c4-muted: #b7aa9b;
  --c4-line: #3c342c;
  --c4-line-strong: #5a4d40;
  --c4-accent: #d4bc86;
  --c4-accent-ink: #d4bc86;
  --c4-danger: #ff5a45;
  --c4-coral: #ff8a7a;
  --c4-mint: #2f6b52;
  --c4-pos: #8ee0b5;
  --c4-neg: #ff8d82;
  --c4-shadow: 0 16px 40px rgba(0, 0, 0, 0.28);
  --c4-hover: #2e2824;
}

[data-crmv4-root][data-theme="light"] {
  --c4-page: #f4f0e8;
  --c4-card: #fffdf8;
}

[data-crmv4-root] * { box-sizing: border-box; }

[data-crmv4-root] .c4-top {
  grid-column: 1;
  grid-row: 1;
  z-index: 20;
  display: flex;
  align-items: stretch;
  min-width: 0;
  box-sizing: border-box;
  min-height: calc(58px + var(--chrome-pad));
  padding-top: calc(env(safe-area-inset-top, 0px) + var(--chrome-pad));
  padding-bottom: var(--chrome-pad);
  padding-left: calc(env(safe-area-inset-left, 0px) + var(--chrome-pad));
  padding-right: calc(env(safe-area-inset-right, 0px) + var(--chrome-pad));
  background: var(--c4-card);
  border-bottom: 1px solid var(--c4-line);
}

[data-crmv4-root] .c4-logo {
  width: auto;
  height: 26px;
}

[data-crmv4-root] .c4-brand {
  display: flex;
  align-items: center;
  padding-inline: 8px 12px;
  border-inline-end: 1px solid var(--c4-line);
}

[data-crmv4-root] .c4-nav {
  display: none;
  min-width: 0;
  flex: 1;
}

[data-crmv4-root] .c4-nav-item {
  position: relative;
  display: flex;
  min-width: 0;
  flex: 0 1 auto;
  flex-direction: column;
  justify-content: center;
  gap: 1px;
  padding: 6px 12px 8px;
  border: 0;
  border-inline-end: 1px solid var(--c4-line);
  background: transparent;
  color: inherit;
  text-align: start;
  cursor: pointer;
  text-decoration: none;
}

[data-crmv4-root] .c4-nav-item[data-on="1"]::before {
  content: "";
  position: absolute;
  top: 0;
  inset-inline: 10px;
  height: 5px;
  border-radius: 0 0 2px 2px;
  background: var(--c4-accent);
}

[data-crmv4-root] .c4-nav-title {
  font-size: 13px;
  font-weight: 600;
  line-height: 16px;
  letter-spacing: 0.01em;
  white-space: nowrap;
}

[data-crmv4-root] .c4-nav-sub {
  display: none;
  color: var(--c4-muted);
  font-size: 11px;
  font-weight: 500;
  line-height: 13px;
}

[data-crmv4-root] .c4-count {
  position: absolute;
  top: 6px;
  inset-inline-end: 6px;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 8px;
  background: var(--c4-coral);
  color: #fff;
  font-size: 10px;
  line-height: 16px;
  text-align: center;
}

[data-crmv4-root] .c4-drop { position: relative; display: flex; min-width: 0; flex: 0 1 auto; }
[data-crmv4-root] .c4-drop .c4-nav-item { flex: 1; width: 100%; }

[data-crmv4-root] .c4-drop-menu {
  position: absolute;
  z-index: 30;
  top: calc(100% - 2px);
  inset-inline-start: 6px;
  display: none;
  min-width: 188px;
  flex-direction: column;
  gap: 2px;
  padding: 6px;
  border: 1px solid var(--c4-line);
  border-radius: 8px;
  background: var(--c4-card);
  box-shadow: var(--c4-shadow);
}

[data-crmv4-root] .c4-drop[data-open="1"] .c4-drop-menu { display: flex; }

[data-crmv4-root] .c4-drop-menu a {
  padding: 8px 10px;
  border-radius: 4px;
  color: inherit;
  font-size: 13px;
  text-decoration: none;
}

[data-crmv4-root] .c4-drop-menu a:hover,
[data-crmv4-root] .c4-drop-menu a[data-on="1"] { background: var(--c4-table); }

[data-crmv4-root] .c4-gear .c4-nav-title { display: flex; align-items: center; min-height: 16px; }

[data-crmv4-root] .c4-top-tools {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-inline-start: auto;
}

[data-crmv4-root] .c4-frame {
  grid-column: 1;
  grid-row: 2;
  display: flex;
  min-width: 0;
  min-height: 0;
  flex-direction: column;
}

[data-crmv4-root] .c4-panel {
  display: flex;
  min-width: 0;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  margin: 8px;
  overflow: auto;
  border: 1px solid var(--c4-line);
  border-radius: 8px;
  background: var(--c4-canvas);
  box-shadow: var(--c4-shadow);
}

[data-crmv4-root] .c4-pagehead {
  display: flex;
  min-height: 55px;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 15px;
  margin: 15px 15px 0;
  padding: 8px 15px;
  border: 1px solid var(--c4-line);
  border-radius: 8px;
  background: var(--c4-card);
}

[data-crmv4-root] .c4-page-title {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: 0.06em;
  line-height: 1.15;
}

[data-crmv4-root] .c4-page-sub {
  margin: 2px 0 0;
  color: var(--c4-muted);
  font-size: 11px;
  font-weight: 500;
}

[data-crmv4-root] .c4-page-search {
  display: flex;
  min-width: 0;
  flex: 1 1 180px;
  margin-inline-start: auto;
}

[data-crmv4-root] .c4-page-search .c4-field { width: 100%; }

[data-crmv4-root] .c4-stage {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: 15px;
  padding: 15px;
}

[data-crmv4-root] .c4-foot {
  margin-top: auto;
  padding: var(--chrome-pad);
  color: var(--c4-muted);
  font-size: 11px;
  text-align: center;
}

[data-crmv4-root] .c4-rail,
[data-crmv4-root] .c4-page-rail { display: none; }

[data-crmv4-root] .c4-page-rail {
  min-width: 0;
  min-height: 0;
  flex-direction: column;
  gap: 8px;
  overflow: auto;
  padding: 10px 8px calc(env(safe-area-inset-bottom, 0px) + var(--chrome-pad));
  border-inline-end: 1px solid var(--c4-line);
  background:
    linear-gradient(180deg, rgba(166, 133, 78, 0.16), transparent 28%),
    var(--c4-card);
}

[data-crmv4-root] .c4-page-rail section { display: grid; gap: 2px; }
[data-crmv4-root] .c4-page-rail h3,
[data-crmv4-root] .c4-grouped-menu h3 {
  margin: 8px 0 0;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
[data-crmv4-root] .c4-page-rail section[data-on="1"] > h3 { color: var(--c4-accent-ink); }
[data-crmv4-root] .c4-rail-link {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  min-width: 0;
  padding: 4px 6px;
  border-radius: 8px;
  color: inherit;
  font-size: 13px;
  text-decoration: none;
}
[data-crmv4-root] .c4-rail-link[data-on="1"] {
  background: rgba(166, 133, 78, 0.16);
  box-shadow: inset 3px 0 0 var(--c4-accent);
}
[data-crmv4-root] .c4-rail-link:focus-visible,
[data-crmv4-root] .c4-rail-fold:focus-visible,
[data-crmv4-root] .c4-nav-item:focus-visible,
[data-crmv4-root] .c4-tab:focus-visible {
  outline: 2px solid var(--c4-accent-ink);
  outline-offset: 2px;
}
[data-crmv4-root] .c4-rail-mark {
  display: grid;
  width: 22px;
  height: 22px;
  flex: 0 0 22px;
  place-items: center;
  border-radius: 6px;
  background: #2a2622;
  color: #f6f1e8;
  font-size: 11px;
}
[data-crmv4-root] .c4-rail-fold,
[data-crmv4-root] .c4-rail-here,
[data-crmv4-root] .c4-rail-note { margin: 0; }
[data-crmv4-root] .c4-rail-fold {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  padding: 4px 6px;
  border: 1px solid rgba(166, 133, 78, 0.45);
  border-radius: 8px;
  background: transparent;
  color: inherit;
  text-align: start;
  cursor: pointer;
}
[data-crmv4-root][data-fold="1"] .c4-page-rail .c4-rail-name,
[data-crmv4-root][data-fold="1"] .c4-page-rail .c4-rail-here,
[data-crmv4-root][data-fold="1"] .c4-page-rail .c4-rail-note,
[data-crmv4-root][data-fold="1"] .c4-page-rail .c4-rail-find,
[data-crmv4-root][data-fold="1"] .c4-page-rail h3,
[data-crmv4-root][data-fold="1"] .c4-page-rail .c4-smart-rail { display: none; }
[data-crmv4-root] .c4-gear-menu {
  max-height: min(70dvh, 540px);
  min-width: 240px;
  overflow: auto;
}
[data-crmv4-root] .c4-more-luxe .c4-rail-link {
  border: 1px solid var(--c4-line);
  background: var(--c4-card);
}
[data-crmv4-root][data-theme="dark"] .c4-avatar { color: #221f1b; }

[data-crmv4-root] .c4-profile-main .c4-mini-nav { position: static; }
[data-crmv4-root] .c4-record-head {
  position: sticky;
  top: 0;
  z-index: 6;
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 12px;
  border: 1px solid rgba(166, 133, 78, 0.45);
  border-radius: 16px;
  background:
    linear-gradient(165deg, rgba(166, 133, 78, 0.14), transparent 42%),
    #fffdf8;
}
[data-crmv4-root] .c4-record-head h2,
[data-crmv4-root] .c4-record-head h3 { margin: 0; font-weight: 500; }
[data-crmv4-root] .c4-record-id { display: flex; gap: 10px; align-items: center; min-width: 0; }
[data-crmv4-root] .c4-record-id p { margin: 0; overflow-wrap: anywhere; }
[data-crmv4-root] .c4-record-mark {
  display: grid;
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  place-items: center;
  border-radius: 10px;
  background: #2a2622;
  color: #f6f1e8;
  font-size: 13px;
}
[data-crmv4-root] .c4-record-chips,
[data-crmv4-root] .c4-record-acts .c4-line-filters,
[data-crmv4-root] .c4-record-tools { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
[data-crmv4-root] .c4-record-figs ul,
[data-crmv4-root] .c4-smart-rail ul { margin: 0; padding: 0; list-style: none; }
[data-crmv4-root] .c4-list-desk,
[data-crmv4-root] .c4-list-rows li {
  border: 1px solid rgba(166, 133, 78, 0.4);
  border-radius: 12px;
  background: #fffdf8;
}
[data-crmv4-root] .c4-list-desk { display: grid; gap: 8px; padding: 12px; }
[data-crmv4-root] .c4-list-rows { display: grid; gap: 6px; margin: 0; padding: 0; list-style: none; }
[data-crmv4-root] .c4-list-rows li { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; padding: 8px; }
[data-crmv4-root] .c4-list-rows li[data-on="1"] { box-shadow: inset 3px 0 0 #a6854e; }

[data-crmv4-root] .c4-insight-luxe,
[data-crmv4-root] .c4-pref-luxe {
  display: grid;
  gap: 12px;
  padding: 14px;
  border: 1px solid rgba(166, 133, 78, 0.45);
  border-radius: 16px;
  background:
    linear-gradient(165deg, rgba(166, 133, 78, 0.12), transparent 46%),
    #fffdf8;
}
[data-crmv4-root] .c4-insight-luxe .c4-title,
[data-crmv4-root] .c4-pref-luxe .c4-title { margin: 0; font-weight: 500; }
[data-crmv4-root] .c4-bars { display: grid; gap: 6px; }
[data-crmv4-root] .c4-bar-row { display: grid; grid-template-columns: minmax(0, 140px) minmax(0, 1fr) auto; gap: 8px; align-items: center; }
[data-crmv4-root] .c4-bar-track { height: 8px; border-radius: 8px; background: rgba(166, 133, 78, 0.2); }
[data-crmv4-root] .c4-bar-fill { display: block; height: 8px; border-radius: 8px; background: #7a5e30; }
[data-crmv4-root] .c4-insight-luxe table,
[data-crmv4-root] .c4-pref-view { width: 100%; }
[data-crmv4-root] .c4-pref-rows { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; }
[data-crmv4-root] .c4-pref-rows li {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  padding: 10px;
  border: 1px solid rgba(166, 133, 78, 0.35);
  border-radius: 12px;
}
[data-crmv4-root] .c4-pref-view {
  margin: 0;
  max-height: 160px;
  overflow: auto;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font-size: 12px;
}
[data-crmv4-root][data-theme="dark"] .c4-insight-luxe,
[data-crmv4-root][data-theme="dark"] .c4-pref-luxe,
[data-crmv4-root][data-theme="dark"] .c4-pref-rows li { background: #221f1b; color: #f6f1e8; }
[data-crmv4-root][data-theme="dark"] .c4-bar-fill { background: #d4bc86; }

[data-crmv4-root] .c4-book-luxe,
[data-crmv4-root] .c4-agenda-luxe {
  display: grid;
  gap: 10px;
  padding: 14px;
  border: 1px solid rgba(166, 133, 78, 0.45);
  border-radius: 16px;
  background:
    linear-gradient(165deg, rgba(166, 133, 78, 0.12), transparent 46%),
    #fffdf8;
}
[data-crmv4-root] .c4-book-luxe .c4-title,
[data-crmv4-root] .c4-agenda-luxe .c4-title { margin: 0; font-weight: 500; }
[data-crmv4-root] .c4-book-rows,
[data-crmv4-root] .c4-book-sum,
[data-crmv4-root] .c4-agenda-lane,
[data-crmv4-root] .c4-agenda-grid ul { margin: 0; padding: 0; list-style: none; }
[data-crmv4-root] .c4-book-rows li,
[data-crmv4-root] .c4-agenda-lane li,
[data-crmv4-root] .c4-agenda-grid li {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  padding: 8px 0;
  border-top: 1px solid var(--c4-line);
}
[data-crmv4-root] .c4-agenda-grid { display: grid; gap: 10px; }
[data-crmv4-root] .c4-agenda-grid section[data-today="1"] { box-shadow: inset 3px 0 0 #7a5e30; }
[data-crmv4-root][data-theme="dark"] .c4-book-luxe,
[data-crmv4-root][data-theme="dark"] .c4-agenda-luxe { background: #221f1b; color: #f6f1e8; }

[data-crmv4-root] .c4-lux-list,
[data-crmv4-root] .c4-note-studio,
[data-crmv4-root] .c4-lux-cards li {
  border: 1px solid rgba(166, 133, 78, 0.4);
  border-radius: 16px;
  background:
    linear-gradient(165deg, rgba(166, 133, 78, 0.1), transparent 48%),
    #fffdf8;
}
[data-crmv4-root] .c4-lux-list,
[data-crmv4-root] .c4-note-studio { display: grid; gap: 10px; padding: 14px; }
[data-crmv4-root] .c4-lux-list .c4-title,
[data-crmv4-root] .c4-note-studio .c4-title { margin: 0; font-weight: 500; color: #7a5e30; }
[data-crmv4-root] .c4-lux-desk { display: none; }
[data-crmv4-root] .c4-lux-cards { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; }
[data-crmv4-root] .c4-lux-cards li { display: grid; gap: 4px; padding: 10px; }
[data-crmv4-root] .c4-lux-cards p { margin: 0; }
[data-crmv4-root] .c4-lux-desk thead th {
  position: sticky;
  top: 0;
  z-index: 4;
  background: #fffdf8;
  color: #7a5e30;
  font-weight: 500;
  font-size: 11px;
}
[data-crmv4-root] .c4-lux-list[data-dense="1"] td { padding: 4px 8px; font-size: 12px; }
[data-crmv4-root] .c4-note-rows,
[data-crmv4-root] .c4-task-rows { margin: 0; padding: 0; list-style: none; }
[data-crmv4-root] .c4-note-rows li,
[data-crmv4-root] .c4-task-rows li { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; padding: 8px 0; border-top: 1px solid var(--c4-line); }
[data-crmv4-root] .c4-note-rows li[data-pinned="1"] { box-shadow: inset 3px 0 0 #7a5e30; }
[data-crmv4-root] .c4-note-rows mark { background: transparent; color: #7a5e30; font-weight: 500; }
[data-crmv4-root][data-theme="dark"] .c4-lux-list,
[data-crmv4-root][data-theme="dark"] .c4-note-studio,
[data-crmv4-root][data-theme="dark"] .c4-lux-cards li,
[data-crmv4-root][data-theme="dark"] .c4-lux-desk thead th { background: #221f1b; color: #f6f1e8; }
[data-crmv4-root][data-theme="dark"] .c4-lux-list .c4-title,
[data-crmv4-root][data-theme="dark"] .c4-note-studio .c4-title,
[data-crmv4-root][data-theme="dark"] .c4-lux-desk thead th,
[data-crmv4-root][data-theme="dark"] .c4-note-rows mark { color: #d4bc86; }
@media (min-width: 768px) {
  [data-crmv4-root] .c4-lux-desk { display: block; }
  [data-crmv4-root] .c4-lux-cards { display: none; }
}

[data-crmv4-root] .c4-today-hero,
[data-crmv4-root] .c4-staff-luxe,
[data-crmv4-root] .c4-staff-cards li,
[data-crmv4-root] .c4-today-counts a {
  border: 1px solid rgba(166, 133, 78, 0.45);
  border-radius: 16px;
  background:
    linear-gradient(165deg, rgba(166, 133, 78, 0.12), transparent 48%),
    #fffdf8;
}
[data-crmv4-root] .c4-today-hero,
[data-crmv4-root] .c4-staff-luxe { display: grid; gap: 10px; padding: 14px; }
[data-crmv4-root] .c4-today-hero .c4-title,
[data-crmv4-root] .c4-staff-luxe .c4-title { margin: 0; font-weight: 500; color: #7a5e30; }
[data-crmv4-root] .c4-today-counts,
[data-crmv4-root] .c4-today-money,
[data-crmv4-root] .c4-staff-cards { display: grid; gap: 8px; }
[data-crmv4-root] .c4-today-counts { grid-template-columns: repeat(2, minmax(0, 1fr)); }
[data-crmv4-root] .c4-today-counts a {
